INSERT INTO public.pillars (name, description, icon, pre_prompt, display_order) VALUES
('Technique', 'Améliorez votre swing, votre posture et vos fondamentaux techniques.', 'target', 'Tu es dans le pilier Technique. Concentre-toi sur les aspects techniques du golf : swing, grip, posture, alignement, et fondamentaux. Donne des conseils précis et actionnables basés sur la méthode de Mathieu.', 1),
('Mental', 'Développez votre concentration, gestion du stress et confiance.', 'brain', 'Tu es dans le pilier Mental. Concentre-toi sur les aspects mentaux du golf : concentration, gestion du stress, confiance en soi, visualisation, et préparation mentale. Donne des conseils basés sur la méthode de Mathieu.', 2),
('Physique', 'Optimisez votre préparation physique et prévention des blessures.', 'dumbbell', 'Tu es dans le pilier Physique. Concentre-toi sur la préparation physique du golfeur : échauffement, étirements, renforcement musculaire, souplesse, et prévention des blessures. Donne des conseils basés sur la méthode de Mathieu.', 3),
('Stratégie', 'Maîtrisez la gestion du parcours et la prise de décision.', 'map', 'Tu es dans le pilier Stratégie. Concentre-toi sur la gestion du parcours : choix de clubs, lecture du terrain, gestion des risques, stratégie de jeu, et prise de décision. Donne des conseils basés sur la méthode de Mathieu.', 4),
('Matériel', 'Choisissez et adaptez votre équipement pour performer.', 'wrench', 'Tu es dans le pilier Matériel. Concentre-toi sur l''équipement de golf : choix des clubs, fitting, balles, accessoires, et entretien du matériel. Donne des conseils basés sur la méthode de Mathieu.', 5);
